"""Knowledge notes are independently authored; original keys stay intact."""
import re,html,json
from pathlib import Path
NIST='https://www.itl.nist.gov/div898/handbook/'
MS='https://support.microsoft.com/en-us/excel/excel-functions-alphabetical'
RULES=[]
def rule(topic,pattern,body,tip='',source=''):
    RULES.append((topic,re.compile(pattern,re.I),body.split('||'),tip,source))

rule('样本比例与其标准误','样本比例|总体比例|参数“率”',
'设总体比例为 p，独立随机抽样时样本比例 p̂ 的期望为 p，方差为 p(1−p)/n，标准误为 √[p(1−p)/n]。不放回抽取有限总体时，还要考虑有限总体修正。||样本比例本质上是成功次数除以样本量，有限样本下并不严格服从连续正态分布。通常需 np 和 n(1−p) 都足够大，才使用正态近似。不能把“任意样本容量都近似正态”当成结论。','比例标准误：根号下 p(1−p)/n。',NIST)
rule('样本均值的抽样分布','样本均值|样本平均数|样本均数|样本平均|均值抽样|均数的标准误',
'对于独立同分布样本，E(X̄)=μ，Var(X̄)=σ²/n，标准误 SE(X̄)=σ/√n。因此增加样本量不会改变均值的期望，却会缩小标准误。||总体正态时，任意 n 的样本均值都正态；总体非正态时，需要中心极限定理的适用条件和足够大的样本，才能近似正态。并非所有“样本统计量”都会正态。','期望不变，方差除以 n，标准误除以 √n。',NIST)
rule('标准误与标准差','标准误|抽样平均误差',
'标准差描述一组观测值彼此有多分散；标准误描述一个统计量在重复抽样时有多波动，是统计量抽样分布的标准差。二者研究对象不同。||均值的标准误为 σ/√n，σ 未知时常以 s/√n 估计。其他条件相同，样本越大或总体越同质，标准误越小。样本量扩大到原来的4倍，标准误才缩小到一半。','标准差看个体差异；标准误看估计稳定性。',NIST)
rule('t 分布与 t 检验','t分布|t统计量|t检验|T检验|两均值t|总体方差未知|方差未知',
'若总体正态且总体方差未知，用样本标准差 s 代替 σ 后，T=(X̄−μ)/(s/√n) 服从自由度 n−1 的 t 分布。不能因为用了样本方差就仍按已知方差的 Z 检验处理。||t 分布以0为中心、左右对称，尾部比标准正态更厚；自由度越大越接近标准正态。均值在自由度>1时为0，方差在自由度>2时为 ν/(ν−2)，并非所有自由度下均值和方差都存在。||双样本 t 检验用于均值比较；独立、配对、等方差与不等方差情形的公式和自由度不同。','未知方差估均值，先想 t；自由度增大，厚尾变薄。',NIST)
rule('F 分布及方差比检验','F分布|F检验|F统计量|F值|两个总体方差',
'若 U、V 为独立卡方变量，自由度分别为 ν₁、ν₂，则 F=(U/ν₁)/(V/ν₂) 服从 F(ν₁,ν₂)。它非负，通常右偏，由两个有顺序的自由度共同决定。||交换分子分母要取倒数，并交换自由度：若 F~F(ν₁,ν₂)，则 1/F~F(ν₂,ν₁)。临界值还取决于显著性水平与单侧或双侧检验，不能随意交换顺序。||比较方差可用方差比；方差分析也使用 F，但不能据此说 F 直接检验“均值的方差相等”。','F 是两个独立“卡方/自由度”的比值。',NIST)
rule('卡方分布与卡方检验','卡方|χ²|chi.square',
'ν 个独立标准正态变量的平方和服从 χ²(ν)。取值非负，期望是 ν，方差是 2ν；形状随自由度改变，自由度大时逐渐接近正态。||正态总体方差检验用 (n−1)s²/σ₀²，自由度 n−1；r×c 列联表独立性检验的自由度为 (r−1)(c−1)。不同任务的自由度不能混用。||拟合优度和独立性检验中，χ²=Σ(观察频数−期望频数)²/期望频数。值越大通常表示偏离越明显，p 值足够小时拒绝原假设；总体方差检验的拒绝域则按备择假设确定。','卡方：均值 ν，方差 2ν；独立性 df=(行−1)(列−1)。',NIST)
rule('正态分布','正态分布|正态总体|正态曲线|右偏分布',
'正态分布 N(μ,σ²) 关于 μ 对称，均值、中位数、众数都等于 μ。μ 决定位置，σ 决定宽窄：σ 大则宽而矮，σ 小则窄而高，总面积始终为1。||标准正态分布的均值为0、标准差为1。标准化用 Z=(X−μ)/σ。正态分布的取值范围是整个实数轴，不只限于 μ 附近或正数。||“原数据正态”与“统计量正态”应分开判断：正态样本的均值正态，样本方差经过缩放后则是卡方分布。','正态三种中心相同；μ 定位、σ 定宽。',NIST)
rule('置信区间与区间估计','置信|区间估计|可靠度|可靠程度',
'均值置信区间常写作“点估计 ± 临界值×标准误”。总体方差已知时用 Z 临界值；正态总体方差未知时通常用 t 临界值。区间宽度表达估计精度。||在其他条件相同时，提高置信水平会扩大区间；增加样本量会缩短区间；总体变异增大会扩大区间。不能同时无限提高可靠程度和精确程度而不增加信息。||95%置信度的频率学解释是：若反复抽样、按同一方法构造区间，约95%的区间覆盖固定的真实参数；并非已经算出的区间中，固定参数又随机地以95%概率移动。','置信水平高→区间宽；样本量大→区间窄。',NIST)
rule('假设检验的两类错误','第一类|第二类|弃真|取伪|两类错误|显著性水平越小',
'第一类错误是原假设 H₀ 为真却拒绝它，也叫弃真，其概率通常用 α 表示。第二类错误是 H₀ 为假却未拒绝它，也叫取伪，其概率用 β 表示，检验功效为 1−β。||在样本量、效应大小和检验方案等条件固定时，降低 α 常会增加 β。增加有效样本量可以改善检验功效，不能说两类错误在任何情况下都固定互补或相加等于1。','弃真 α；取伪 β；功效 1−β。',NIST)
rule('假设检验、拒绝域与 p 值','假设检验|显著性检验|原假设|备择假设|备选假设|拒绝域|检验统计量|临界|显著性水平|Z检验|z检验',
'先确定 H₀ 和 H₁，再预设显著性水平 α，选择在 H₀ 下分布已知或可近似的统计量，根据样本计算统计量或 p 值，最后作出拒绝或不拒绝 H₀ 的决定。||统计量应与临界值比较，p 值应与 α 比较。若 p≤α，通常拒绝 H₀；不能把统计量的数值直接与 α 比较。α 是在 H₀ 为真时允许的一类错误概率，不是“H₀ 为真的概率”。||H₁ 为“>”通常对应右尾，为“<”对应左尾，为“≠”对应双尾。未拒绝 H₀ 代表证据不足，不证明 H₀ 必然为真。','p 对 α，统计量对临界值；不拒绝≠证明正确。',NIST)
rule('点估计与估计量的优良性','点估计|参数估计|无偏|一致性|有效性|充分统计量|统计量的优良|评价指标',
'点估计用一个样本统计量估计未知总体参数；估计量是抽样前的随机函数，估计值是代入这一次样本后得到的数。区间估计进一步表达抽样不确定性。||无偏性指 E(θ̂)=θ；有效性常在无偏估计量间比较方差，方差小的更稳定；一致性指 n 增大时 θ̂ 依概率趋近 θ；充分性指统计量保留了样本中关于参数的全部信息。||一致性不能仅由“方差趋于0”无条件推出，还需偏差等条件；固定样本的一个估计值也不能称为“必然等于参数”。','无偏看期望，有效看方差，一致看大样本趋近。',NIST)
rule('矩估计与样本矩','矩估计|样本矩|矩统计量|原点矩|中心矩',
'k 阶原点矩是 E(Xᵏ)，样本原点矩为 ΣXᵢᵏ/n；k 阶中心矩围绕均值计算，样本中心矩为 Σ(Xᵢ−X̄)ᵏ/n。第一阶原点矩就是样本均值，第一阶中心矩为0。||矩估计把总体矩中的未知参数与对应样本矩相等，解出参数估计。它属于点估计，不是根据“最可能产生数据”的原则选参数，后者属于极大似然估计。','原点矩围绕0；中心矩围绕均值。',NIST)
rule('极大似然与贝叶斯估计','最大似然|极大似然|贝叶斯估计',
'极大似然估计把已观测样本固定，选择使似然 L(θ)=∏f(xᵢ;θ) 最大的参数。通常取对数把连乘变为连加，再求导、检查边界和极值。它并不等于“让参数本身的概率最大”。||贝叶斯估计为参数赋予先验分布，再用数据得到后验分布：后验∝似然×先验。频率学派常把参数视为固定未知量，贝叶斯方法则以概率分布表达对参数的不确定性。','极大似然：固定数据选参数；贝叶斯：先验+数据→后验。')
rule('归纳推理与演绎推理','归纳|演绎|先尝一尝',
'归纳由若干具体观察推向一般结论，例如用样本推测总体。由于只观察了部分对象，结论通常具有或然性，样本代表性和证据质量十分重要。||演绎由一般前提推到具体结论；前提真实且逻辑形式有效时，结论具有逻辑必然性。假说演绎通常先提出假说，推出可检验预测，再与观察比较，而不是把未经检验的推测当成事实。','归纳：特殊→一般，可能；演绎：一般→特殊，依赖有效前提。')
rule('非参数统计','非参数|顺序统计量|次序统计量',
'非参数方法通常不要求总体必须属于某个已知参数分布族，常利用秩、符号、次序或频数进行推断，但仍可能要求独立性、连续性等条件，并非“完全没有假设”。||中位数、分位数、极值和秩属于常见的位置或次序信息。均值、方差是样本矩相关统计量；不要把“任何样本统计量”都理解为非参数方法。||非参数方法适合偏态、等级等场景，其效率要结合实际分布判断，不能一概说准确度必然高或必然低。','非参数少依赖分布形式，不等于没有条件。',NIST)
rule('总体、样本、参数与统计量','统计量|样本统计|总体参数|总体均数|样本指标|总体特征|样本特征|样本或总体|参数的是|属于参数|样本是|样本的|样本和总体|总体与样本|总体和样本',
'总体是研究目标所涉及的全部单位，样本是从其中抽取的一部分单位。参数概括总体，例如总体均值 μ；统计量是样本的函数，例如样本均值 X̄，不能在统计量定义中含未知总体参数。||对一个确定总体，参数固定但通常未知；抽样前统计量具有随机性，抽样后算出的统计量值确定。换样本可能得到不同值，但也可能恰好相同。||统计量的抽样分布指重复抽样下该统计量所有可能取值的概率分布，不是样本内每个观测值的分布。','总体用参数，样本用统计量；固定未知≠已知。',NIST)
rule('统计总体的特征和范围','总体|总体单位|全面调查|抽样检查一批|样本容量为|样本单位数|样本量|样本容量|样本数目|调查准确度',
'统计总体依据研究目的界定，具有同质性、大量性和差异性：单位在决定总体归属的共同属性上相同，在其他具体取值上可以不同。总体与总体单位具有相对性，研究范围变化时角色也会变化。||有限总体单位数有限且可界定；无限总体包含理论上无限多的单位。样本容量 n 是抽入的单位个数，不是均值或抽样比例。||合理样本量同时受精度、总体变异、置信水平、抽样方法、成本和研究目的影响。样本大能减少随机误差，却不能自动消除抽样框偏差和测量错误。','先确定研究对象和范围，再区分“全部、个体、抽取的部分”。')
rule('分层抽样与整群抽样的区别','整群.*分层|分层.*整群',
'分层抽样先把总体分成互不重叠的层，再在每一层抽若干单位，目的是保证各层代表性并降低误差；有效分层通常层内相似、层间差异较大。||整群抽样把总体分为互不重叠的群，抽取一部分群，对抽中群内的单位全部调查。它通常便于组织、节省成本，但群内相关性高时误差可能增大。||“每组都抽一些”是分层；“只抽部分组，组内全查”是整群；“抽组后组内再抽一部分”则是多阶段。','分层每层抽，整群抽群全查，多阶段群内再抽。')
rule('分层随机抽样','分层|各年龄组按比例|高级.*中级.*职称|高级学历|疫苗接种率',
'先按与调查变量有关的特征分成互不重叠、合起来覆盖总体的层，再分别随机抽样。各层都应有样本，层内同质程度越高，通常越有利于提高精度。||比例分配时 nₕ=n×Nₕ/N。例如各层人数占比为20%、30%、50%，总样本100，则分别抽20、30、50。配额抽样也分组分配名额，但组内未必随机，所以属于非概率方法。','比例分层：各层样本量=总样本量×各层占比。')
rule('整群抽样','整群|群集|以群为单位|以之为抽样单位',
'把总体分成互不重叠、互不遗漏的群，以群为抽样单位随机抽取部分群，再调查抽中群内全部个体。学校、街区、工厂等自然集合经常被作为群。||优点是便于集中调查、减少交通和组织成本；群内单位相似度高时，有效信息可能少于同规模的简单随机样本，因此精度并非它的必然优势。||若群大小悬殊，可考虑与规模成比例的抽取及相应权重，不能忽略群规模导致的入样概率差异。','整群省组织成本，但不保证误差最小。')
rule('系统抽样与等距抽样','系统抽样|等距抽样|样本距离|每隔一定|系统随机|身份证号码',
'将总体按一定顺序排列，确定抽样间隔 k≈N/n，先随机选择起点，再依间隔依次抽取。比如 N=1000、n=100，间隔10，起点 r 在1至10中随机选，抽 r、r+10、…、r+990。||总体排序可按有关标志、无关标志或自然顺序。必须注意与间隔一致的周期性，否则可能发生系统偏差。随机起点是概率抽样的重要条件，固定挑一个方便起点并不等价。||当 N/n 非整数时，要采用明确的舍弃、循环或小数间隔方案，不能不加说明地随意漏掉一部分总体。','系统抽样=排序+间隔+随机起点；警惕周期性。')
rule('简单随机抽样','简单随机|抽签|随机数表|每个球|相同的入样概率|抽取样本的原则|随机抽样|抽样设计|设计抽样方案|统计抽样|概率抽样|常用的抽样方法|常用的抽样调查方法',
'简单随机抽样依随机机制抽取，在固定样本量的不放回设计中，每个可能样本有相同的被抽中机会。抽签、随机数表或随机数发生器是常见实现方式，编号只需唯一，不必机械限定为从1开始。||概率抽样还包括系统、分层、整群、多阶段等方法；判断、便利、配额和滚雪球通常属于非概率抽样，不能只因“看起来有代表性”就称为随机抽样。||设计需服务于研究目的、可操作、兼顾成本，并能评价精度。样本大并不保证某一次样本毫无偏离，也不意味着调查无需完整抽样框。','随机性来自抽取机制，不来自研究者的主观判断。')
rule('多阶段抽样','多阶段|多段抽样|二阶段|先.*学校.*再',
'多阶段抽样逐级抽取单位，例如先抽学校，再从抽中学校抽学生。不同阶段的抽样单位和方法可以不同，最终个体的入样概率由各阶段共同决定。||它适合总体分散、规模很大的调查，便于组织并降低成本；缺点是设计、权重和误差计算较复杂，多级聚集也可能增加误差。||如果抽中学校内所有学生都调查，属于一次整群抽样；如果还抽一部分学生，才体现第二阶段抽取。','先抽大单位，再抽小单位；每级都要有清楚的抽取规则。')
rule('滚雪球抽样','滚雪球',
'先找到少量符合条件的对象，再请其推荐其他符合条件者，如此扩展样本。它通常用于难以建立抽样框、隐蔽或不易接触的人群。||优势是进入特殊群体较容易、能获得较深入的信息；局限是依赖关系网络，样本可能集中于某些圈子，入样概率通常未知，不能据此保证总体代表性或无偏。||“任何人群都适用、误差必然更小、可直接作严格概率推断”都超过了这种方法能保证的范围。','滚雪球靠推荐，适合难接触群体；网络偏差要警惕。')
rule('配额、判断与便利抽样','配额|判断抽样|判断取样|任意抽样|便利抽样|非随机|非概率',
'便利（任意）抽样按容易接触选对象；判断抽样由研究者凭经验选对象；配额抽样先分配类别名额，再选满名额。这些方法通常没有已知的随机入样概率。||它们可省时省钱、用于探索研究，但主观偏差和选择偏差难以量化。配额结构像分层抽样，不代表每层都随机；判断“有代表性”也不能替代概率抽取。||不能直接用简单随机抽样的误差公式，宣称这些样本的误差必然很小。','分配名额≠层内随机；方便或经验选择属于非概率。')
rule('抽样误差、非抽样误差与偏倚','抽样误差|代表性误差|偶然误差|随机误差|系统误差|系统性误差|登记|计算误差|误差|偏倚',
'抽样误差来自只调查总体的一部分，即使严格随机也会因抽样波动产生。样本量增大、总体变异减小、设计更合适，通常能降低随机误差，但不能保证一次估计恰好等于真值。||登记、测量、录入、计算、漏报、无回答及抽样框遗漏等属于非抽样误差；它们在普查中也可能出现。系统偏差具有方向性，不能靠单纯增加样本量抵消。||总体真值通常未知，所以本次估计与真值之间的实际误差通常也未知；实践中用标准误和误差界限评价，而非声称实际误差总能直接算出。','抽样误差靠设计和样本量控制；偏差要改调查过程。')
rule('抽样极限误差与概率度','极限误差|概率度|最大可能范围',
'常见教材记号为 Δ=z×SE：Δ 是给定置信水平下的抽样误差界限，SE 是抽样标准误，z 是相应的概率度或临界值。三者不是互相独立的量。||固定标准误时，要求更高置信水平需要更大的 z 和更宽的误差界限；固定误差界限而提高置信水平，则要降低标准误，通常需要增大样本量。||这里的“最大误差”是对应概率保证程度的界限，并非随机抽样所有可能结果都绝对不会越界。','误差界限=临界值×标准误。',NIST)
rule('集中趋势、位置与离散程度','集中趋势|集中位置|位置平均数|描述数据位置|平均数|中位数|众数|极差|离散|分散|标准差|方差|偏态|偏度|峰度|分布形状|四分位',
'均值、中位数、众数描述中心位置；极差、方差、标准差、四分位距描述离散程度。均值利用全部数值但易受极端值影响，中位数和四分位数对极端值较稳健，偏态数据常优先看中位数。||将数据排序后，奇数个取中间值，偶数个取中间两个的平均数；众数是频数最多的值，可能不唯一；极差=最大值−最小值，方差=标准差²。||偏度衡量不对称，正偏为右长尾、负偏为左长尾；峰度反映尾部及极端值特征。正态分布的普通峰度为3、超额峰度为0，须先分清定义。','中心看均值/中位数/众数；分散看差；形状看偏峰。',NIST)
rule('协方差与相关系数','相关系数|相关关系|正相关|负相关|协方差|相关程度',
'协方差 Cov(X,Y)=E[(X−EX)(Y−EY)] 表示共同变化方向，但大小受单位影响。相关系数 r=Cov(X,Y)/(σXσY) 消除量纲，范围在−1到1之间，绝对值越大表示线性相关越强。||r>0 为同向，r<0 为反向，r≈0 只表示线性关系弱，并不排除非线性关系，更不能推出独立；相关也不等于因果。||协方差矩阵对称，对角线是各变量方差，非对角线是成对协方差；方差非负，协方差可以为负。','r 看符号和绝对值；相关≠因果，零相关≠没关系。',NIST)
rule('测量尺度与变量类型','定类|定序|定距|定比|尺度|定性|定量|数值型|顺序变量|顺序数据|类别|分类变量|连续数值|定量变量|变量中',
'定类只分组，无天然顺序，如职业、血型；定序可排序，但等级间差距不能当成等距，如满意度和产品等级。给类别编数字不会自动把它变成可做算术的定量数据。||定距有相等单位间隔，但零点人为，如摄氏温度和日历年份，可解释差值，不能说20℃是10℃的两倍热。定比还具有绝对零点，如长度、重量、收入，可比较倍数。||测量层次从低到高为定类→定序→定距→定比。高层次可降级处理，反过来不行；定量变量还分离散型与连续型。','类只分、序能排、距可减、比可乘除。')
rule('相对指标和统计指数','相对|比重|及格率|出勤率|人均|恩格尔|统计指数',
'结构相对数=部分/总体，比例相对数=同一总体不同部分相互比较；比较相对数比较同一时期不同对象的同类指标；动态相对数比较同一对象不同时期的同类指标。||强度相对数以两个有关但性质不同的总量相除，如人口密度、人均产量，常有“人/平方公里、千克/人”等复合单位，并非所有相对数都是无名数。||计划完成程度=实际/计划×100%。对越大越好的指标超过100%常表示超额；对成本、能耗等越低越好的指标，不能机械认为超过100%就好。恩格尔系数降低表示食品支出占比降低，不能单凭它推断食品支出绝对额下降。','结构部分比整体，比例部分比部分；计划要看指标方向。')
rule('总量指标、数量指标与质量指标','总量|绝对指标|实物指标|价值指标|质量指标|数量指标|计量单位|统计指标|指标数值|业务指标中能用数量',
'总量指标反映总体规模或总水平，有明确时空范围和计量单位，例如产量、销售额、人数。实物单位如吨、台，价值单位如元，劳动单位如工时。||时期指标是一段时间内累计发生量，如月销售额；时点指标是某一时刻的存量，如年末库存。时期指标可按不重叠时期累加，时点存量一般不能直接跨时点相加。||数量指标侧重规模，质量指标侧重效率、水平或相互关系，如平均价格、利润率、劳动生产率。不要把任何一个“用数字表示”的指标都叫数量指标或总量指标。','规模看数量，效率看质量；时期是流量，时点是存量。')
rule('线性回归与最小二乘','线性回归|回归方程|回归模型|多元回归|最小二乘|决定系数|判定系数|回归和分类',
'一元回归写为 y=β₀+β₁x+ε，β₀ 为截距、β₁ 为斜率，ε 为未解释的扰动。最小二乘选择参数使残差平方和 Σ(yᵢ−ŷᵢ)² 最小，不是使残差和或绝对值和最小。||“线性”通常指对参数线性，解释变量可以含 x² 等变换项。回归预测数值，分类预测类别；回归系数可正可负，取决于控制其他变量后的方向。||带截距的常规最小二乘中 R²=1−SSE/SST，范围0至1，表示样本内变异被解释的比例；一元回归中等于 Pearson r²。拟合好不等于因果成立，也不保证样本外预测好。','最小二乘最小化残差平方和；R² 不带方向。')
rule('方差分析','方差分析|因子.*一元|各水平的效应',
'方差分析用组间差异相对于组内随机波动的大小检验总体均值是否相同。单因素 K 组、总样本 N 时，组间自由度 K−1，组内自由度 N−K，F=组间均方/组内均方。||原假设是各组总体均值全相等，拒绝后只能说“至少有一组均值不同”，不能说每两组都不同，需要进一步比较才能定位。组内方差小也不能单独推出组间差异小。||经典模型通常要求观测独立、组内误差近似正态、各组方差相等；因子可以一个也可以多个，所以还有双因素和多因素方差分析。','ANOVA 用方差比，检验的是均值；拒绝=不全相等。',NIST)
rule('朴素贝叶斯分类','朴素贝叶斯|贝叶斯分类',
'贝叶斯分类按后验概率 P(类别|特征) 选择类别。朴素贝叶斯的“朴素”是给定类别后，各特征条件独立的假设，并非无条件要求所有特征彼此独立。||后验与“类别先验×各特征条件概率的乘积”成比例；取对数可避免很小概率连乘下溢，平滑可处理零频次。它既可二分类，也可多分类。||训练不需要复杂的迭代求最优边界，但预测仍需参数估计；相关特征可能削弱独立假设，不能据此断言算法完全不能用。','给定类别后条件独立；先验×似然比后验。')
rule('决策树与节点划分','决策树|父节点|子节点|叶子节|CART|C4.5|信息增益',
'决策树从根节点开始按特征条件逐层分支，内部节点作判断，叶节点给出类别或预测值。叶节点没有进一步分支，因此不是“仍可充当中间节点”的同一角色。||ID3 常用信息增益，C4.5 用信息增益率，CART 分类常用基尼指数、回归常用平方误差。不能把各算法的划分标准互换。||划分追求降低加权平均不纯度，不能保证每一个子节点的熵都严格小于父节点。深树易过拟合，可用深度限制、最小样本量或剪枝控制。','ID3 增益，C4.5 增益率，CART 分类基尼；叶节点不再分。')
rule('聚类与 K 均值','聚类|K均值|K-means|K 均值',
'聚类是按相似性把对象分组的无监督学习，通常不依赖预先标好的类别。分类则学习已标注样本的类别规律，二者目标和训练信息不同。||K 均值先选 K 个中心，反复把样本分给最近中心，再以簇内均值更新中心，通常降低簇内平方距离和。需预先给 K，可能依赖初值、落入局部最优，对尺度和离群值敏感。||它偏好近似球状、尺度相近的数值簇，不能认为对任意形状、任意非数值数据都直接适用。','聚类无标签；K 均值：分配→更新，初值和尺度重要。')
rule('机器学习的任务与标签','机器学习|监督|分类模型|二分类|客户的流失|分类和回归|逻辑回归',
'监督学习以带目标标签的训练样本学习输入到输出的映射：分类预测离散类别，回归预测连续数值。客户是否流失通常是二分类，可用逻辑回归、分类树等模型。||无监督学习通常没有目标标签，常见任务为聚类和降维；半监督学习同时利用少量标注和大量未标注样本。并非训练流程只有输入与输出，还包括预处理、拟合、验证和评估。||逻辑回归虽然名字含“回归”，常用于分类，将线性评分经 sigmoid 映射为0至1的概率；需要阈值才得到类别。','有标签学分类/回归，无标签做聚类/降维。')
rule('降维与特征表示','降维|主成分',
'降维将高维特征映射或筛选为较少维度，在尽量保留重要结构和信息的同时降低冗余、噪声与计算成本。通常是高维到低维，而不是反过来扩维。||特征选择保留原特征的子集；特征提取构造新特征，如主成分分析以方差方向构造线性组合。降维一般存在信息取舍，不能保证毫无信息损失或必然提高所有模型准确率。','降维减少特征维度；选择保留原列，提取产生新列。')
rule('线性规划与单纯形法','线性规划|单纯形|图解法|可行域',
'线性规划由决策变量、线性目标和线性约束组成，可求最大值或最小值。可行域是所有约束的公共交集；无可行解、无界和存在多个最优解都是可能结果。||在适当的标准型条件下，若存在有限最优解，可在基本可行解中找到最优解；二维图解用等值线沿改进方向移动，寻找可行边界上的最优位置。||单纯形法围绕基本可行解迭代，确定初始基、入基变量、出基变量和最优性判据；并非任意顶点都是最优，也不能认为最优解必唯一。','先可行，再优化；线性规划可能无解、无界或多解。')
rule('整数规划与分支定界','整数规划|整数线性|混合整数|纯整数|0-1|分支|分枝|隐枚举',
'整数规划要求部分或全部决策变量取整数；全部整数为纯整数、部分整数为混合整数，0-1规划要求指定变量只能取0或1，限制的是变量而不是目标函数系数。||去掉整数限制得到线性松弛。最大化问题的松弛最优值给出上界，已找到的整数可行解给出下界；最小化问题方向相反。不能简单四舍五入松弛解来保证可行或最优。||分支定界对非整数变量分支，并用界限剪枝：子问题不可行、界不可能改善当前解、或已得到该节点整数最优解时，可终止该节点的进一步分支。','最大化：松弛上界、整数下界；0-1限制变量。')
rule('非线性优化与梯度方法','梯度|牛顿法|一维搜索|单峰|非线性|KKT|拉格朗日|系统优化|优化模型|数学建模|数学模型',
'优化模型用变量、目标和约束表达问题。无约束可微最小化的梯度下降沿负梯度更新 xₖ₊₁=xₖ−αₖ∇f(xₖ)，步长影响收敛；正梯度通常是局部增大最快方向。||牛顿法利用二阶导数或 Hessian 构造方向，不能把一阶梯度方向与牛顿方向混同。共轭梯度利用共轭方向，在正定二次函数的精确运算下有有限步性质，一般非线性情形不能照搬保证。||一维搜索在给定方向上选步长；约束问题可用拉格朗日或 KKT 条件。一般非凸问题的局部最优不保证全局最优，建模假设需服务实际、接受验证。','最小化走负梯度；局部最优不自动等于全局最优。')
rule('云计算的模式与特点','云计算|SaaS|PaaS|IaaS|虚拟化|公有云|私有云',
'云计算通过网络按需提供可配置的计算、存储、网络和软件资源，强调资源池化、弹性扩缩、广泛网络访问和可计量服务。虚拟化是常见实现技术，但不等同于云计算全部内容。||IaaS 提供计算与存储等基础设施，PaaS 提供应用开发运行平台，SaaS 提供可直接使用的软件。公有云面向广泛客户，私有云为特定组织专用，混合云连接不同云环境。||高可用与冗余能降低风险，却不能保证“完全没有故障或安全风险”；按需和弹性也不代表资源无限、费用永远固定。','I 基础设施，P 平台，S 软件；高可靠≠零风险。','https://csrc.nist.gov/pubs/sp/800/145/final')
rule('数据容量单位','存储单位|存储容量单位|容量单位|计算机存储|单位最大',
'bit 是二进制位，byte 是字节，1 byte=8 bit。常见单位从小到大为 B、KB、MB、GB、TB、PB、EB、ZB、YB，不要把位与字节混为一谈。||严格的十进制前缀每级1000，二进制前缀 KiB、MiB、GiB 每级1024。教材和操作系统有时用 KB/MB 表示1024倍关系，做题时需结合选项约定，而不能认为两种口径永远相同。','B 与 b 不同；K→M→G→T→P→E。')
rule('大数据、数据价值与数据挖掘','大数据|数据价值|数据的价值|数据资源|数据挖掘|啤酒|尿布|数据质量',
'大数据不仅是体量大，还常用 Volume、Velocity、Variety、Value、Veracity 描述规模、速度、多样性、价值和真实性等特征。数据可以结构化、半结构化或非结构化，价值密度低不等于总体价值低。||数据挖掘从数据中发现可用模式，常见任务有分类、回归、聚类和关联规则。“买啤酒也常买尿布”描述商品共同出现，属于关联分析，不直接证明因果。||大量数据仍可能含偏差、噪声和遗漏，需要质量控制、清洗和场景解释；大数据分析不只服务互联网，也可用于医疗、工业、交通等领域。','体量大不等于质量高；关联规则看共现，不推因果。')
rule('数据结构、数据库与存储','NOSQL|非关系型|非结构化|结构化|数据存储|存储时|数据库',
'结构化数据具有明确模式，如关系表的行列；半结构化数据有标签或键等组织方式，如 JSON、XML；非结构化数据如图片、音视频和自由文本。来源内部或外部与结构类型是两个不同维度。||NoSQL 常包括键值、文档、列族和图等模型，不是只能存文本或只能用表格。关系数据库以表和关系为主要模型，数据模型与物理存储方式不能混为一谈。||存储需兼顾容量扩展、检索效率、备份恢复、权限和安全；加密主要保护保密性，不能单靠更严格加密来解决容量增长。','来源和结构分开看；NoSQL 不只键值一种。')
rule('图表选择与可视化','图形|可视化|作图法|图表|条形图|折线图|曲线图|饼图|饼状图|散点图|直方图|箱型|箱线|热力图|频数分布',
'比较不同类别的数量通常用条形或柱形图，条长表示数值，类别由坐标或标签区分；观察时间趋势通常用折线图；看两数值变量关系用散点图，每个点是一对观测。||直方图对连续数值分组，柱面积反映频数或频率；组距不等时需看密度而非只看高度。箱线图展示中位数、四分位数与离群情况；热力图以颜色编码矩阵数值。||饼图看同一整体内各部分占比，总体通常为100%，类别太多或小比例太多不利辨认。任何图表都不能单独证明广告造成销售上升等因果关系，坐标范围与尺度也要核对。','趋势线、类别柱、占比饼、关系点、分布直方/箱线。')
rule('数据清洗与预处理','清洗|缺失|异常值|数据转换|数据处理|分词|情感分析|主题模型|筛选|排序|数据分组|一致性检查|数据加工|数据集成|文本数据',
'数据清洗处理缺失、重复、异常和不一致，常见方法包括删除、填补、纠正和统一格式。选择方法要看缺失机制、比例和业务意义，不能一律删除或一律填均值。||修剪通常删除极端部分，缩尾将极端值替换为边界值；对数转换改变尺度，不能与修剪等同。异常点也可能是真实重要信号，需先核实。||处理流程还包括集成、转换、筛选、排序、编码和存储。分词、主题分析、情感分析属于文本处理。迭代是基于结果持续检查和改进，不只是机械指定执行次数。','先核实再清洗；删除、填补、变换各有条件。')
rule('数据分析方法与问题构建','验证性|探索性|分析目标|数据分析目标|分析的基本步骤|问题识别|问题构建|构建|数据分析师|表格法|表格设计|综合评价|因素分析|对比分析|分析报告|数据报告',
'分析先明确业务问题、对象、时间范围和衡量指标，再收集与处理数据、探索规律、建模验证，最后将结果转为可执行建议。技术手段必须服务业务目标，而非为用工具而用工具。||探索性分析借助图表和描述统计发现模式、生成假设；验证性分析围绕预先提出的假设设计检验，统计测试是常见工具。两者互补，不是完全割裂。||表格适合精确列示和比较，图形适合直观呈现；因素分析、对比分析和综合评价分别强调驱动因素、基准差异和多指标综合。报告要说明口径、证据和局限。','先问题后数据；探索找线索，验证检假设。')
rule('业务指标与指标体系','指标体系|原子指标|业务指标|战略指标|定位层次|本月交易金额|新客户获取成本|用户增长|点击率|留存率|客单价|行为.*指标|用户的数量|业务层面',
'指标必须有业务含义、统计对象、计算方法和口径，体系应从战略目标逐级分解到部门和执行活动。常见层次为公司、业务或部门、具体运营层，并非任何运营指标都直接等于公司战略指标。||原子指标强调不可再拆的基础度量和聚合逻辑；加上时间、地区等限定可形成衍生指标，完成值、同比、环比等不能不加区分地都叫原子指标。||点击率=点击次数/曝光次数，留存率考察一批用户后续仍活跃的比例，客单价需明确“客户数还是订单数”的口径。指标可分规模、转化、效率、质量等，不能凭一个数就下结论。','指标先定对象、时间和口径；比率必须说清分母。')
rule('企业内外部数据与调查资料','内部数据|内部信息|内部资料|外部数据|外部信息|数据源|数据孤岛|信息源|内部利益|消费者属于|利益相关|社交媒体|行业协会|收集.*数据|观察法|市场调查|客户数据|用户行为数据|符号记载',
'企业内部数据来自日常经营管理，如销售、财务、人事、物流和客户交易；外部数据来自政府、行业协会、竞争者、公开媒体或外部市场研究。结构化或非结构化都可能出现在任一来源。||内部利益相关者通常包含员工、管理层、股东等，消费者、供应商和监管者通常属于外部利益相关者。具体归类应结合关系而不是数据是否放在公司电脑。||一手资料为围绕本次问题直接收集的数据，二手资料是已有资料的再利用。观察法记录实际行为但不一定揭示动机，调查需注意目的、对象、偏差及合法合规。','内部看业务产生地；一手看是否为本次调查直接获取。')
rule('SWOT、竞争环境与战略','SWOT|五力|竞争|战略|情景|CPM|科特勒|市场机会|利润增长|利润增涨|行业环境|宏观经济环境|产业政策',
'战略分析同时考察外部环境和内部条件。SWOT 中 S/W 为内部优势/劣势，O/T 为外部机会/威胁；PEST 侧重政治、经济、社会、技术等宏观环境，波特五力侧重行业竞争结构。||竞争者分析需要识别直接与潜在对手，比较目标、能力、产品、价格、份额及未来反应。CPM 可对关键竞争因素进行加权比较，不能认为它与竞争态势无关。||情景分析针对多种可能未来评估影响和应对；市场机会还要结合需求、竞争和本企业资源能力判断。发现机会不等于一定有盈利，战略也需随环境调整。','内优劣、外机威；宏观看 PEST，行业看五力。')
rule('市场营销、STP 与品牌','营销|市场细分|目标市场|品牌|消费者|市场导向|产品和服务|渠道费用|买方市场|4P',
'STP 为市场细分 Segmentation、目标市场选择 Targeting、市场定位 Positioning。先识别有差异的需求群体，再结合资源和吸引力选择服务对象，明确区别于竞争者的价值定位。||4P 为产品、价格、渠道、促销。营销成本并非只有广告费用，还可能含渠道、促销和获客等成本；市场导向强调识别和满足需求，也可通过创新影响需求。||品牌是识别和区别产品或服务的标识与认知资产；同类产品引入多个品牌属于多品牌策略。市场变化后需要评估定位与策略，而不是一次确定后永远不调整。','STP 细分→选择→定位；4P 产品价格渠道促销。')
rule('风险识别与应对','风险保留|风险回避|风险转移|风险控制|损失控制|投了一份|意外伤害险|融资风险|风险预警',
'风险应对可包括回避、降低或控制、转移和保留。回避是不开展某项风险活动；降低是减少发生概率或损失；转移如保险或合同分担；保留是承担剩余风险。||购买意外保险主要转移部分经济损失，并不消除事故本身。风险保留可能主动也可能被动，通常需结合损失承受力和风险成本，而非认为风险不重要。||预警指标应对应偿债、现金流、融资结构和经营状况等驱动因素，阈值和方向必须有实际依据。','保险转移损失，不消灭事故；保留要有承受力。')
rule('数字鸿沟、算法风险与伦理','数字鸿沟|算法|伦理|职业道德|人类根本利益|道德|数字经济|数字中国|人工智能大会',
'算法风险可能来自带偏差的训练数据、模型不透明、技术漏洞、隐私侵害和责任难以分配。训练数据带入歧视属于数据或算法偏见，黑箱强调人难以理解模型如何作出决定。||可解释性旨在帮助理解、审查、问责和纠错，不代表公开所有商业秘密；风险治理还需数据质量、安全测试、人工监督与申诉机制，不能只靠技术精度。||数字鸿沟是不同群体在接入、技能、使用和受益方面的差距；数据垄断可能阻碍公平竞争和开放共享。职业伦理强调专业责任、诚信、公正及保护相关者利益。','偏见看数据和结果，黑箱看解释，伦理看人的权利与责任。')
rule('法律层级、关系与责任','法律|宪法|法的|行政法规|国务院|司法解释|民事责任|刑事责任|个人信息保护法|数据安全法|专利|法定福利',
'宪法是根本法，具有最高法律效力；全国人大及其常委会制定法律，国务院制定行政法规。法律、行政法规、部门规章与司法解释的制定主体、作用和层级不能混同。||法律关系通常包含主体、客体和内容，内容体现权利义务；法律事实可以引起法律关系发生、变更和消灭。法的规范作用常概括为指引、评价、预测、教育和强制。||法律责任须结合违法行为、损害、因果关系及依法要求的过错等要件，具体责任可能有特殊规则。民事责任常见停止侵害、返还财产、赔偿损失等，刑事责任是严厉的制裁形式。','先看制定主体和法律层级，再看权利义务与责任。','https://flk.npc.gov.cn/')
rule('Excel 单元格、文件与基本操作','Excel|excel|电子表格|行号|列号|日期型数据|文本数据类型',
'Excel 的 A1 引用方式以字母表示列、数字表示行，例如 D4 表示第4列第4行，连续区域用冒号连接。现代 .xlsx 工作表共有1,048,576行、16,384列。||日期通常以序列数保存，显示格式只改变外观；时间是一天的小数部分，显示文本与真实日期值需区分。自动填充可快速生成日期序列。||.xlsx 是常见无宏工作簿格式，.xlsm 可保存宏，.xls 为旧格式。CSV/TXT 适合平面文本数据，通常不能完整保留多工作表、图表和格式。','列字母、行数字；显示格式和单元格实际值分开看。',MS)

# Broad definitions are fallback topics, not overrides for specific calculations.
_broad={'总体、样本、参数与统计量','统计总体的特征和范围','数据清洗与预处理','Excel 单元格、文件与基本操作'}
RULES.sort(key=lambda r:r[0] in _broad)

def plain(s):return html.unescape(re.sub('<[^>]+>','',s or '')).strip()
EXACT=json.loads((Path(__file__).parent/'exact-notes.json').read_text(encoding='utf8'))
def get_explanation(q):
    stem=q['question']
    if stem in EXACT:return EXACT[stem]
    opts=[o.get('text') or plain(o.get('html','')) for o in q['options']]
    chosen=[(o['label'],t) for o,t in zip(q['options'],opts) if o['label'] in q['answer']]
    match=None
    priorities=[('方差分析',r'方差分析|各水平的效应'),('置信区间与区间估计',r'置信|区间估计'),('多阶段抽样',r'多阶段|多段抽样|二阶段'),('抽样极限误差与概率度',r'极限误差|概率度'),('总体、样本、参数与统计量',r'属于参数|属于统计量|样本统计量|是统计量|是参数'),('测量尺度与变量类型',r'定类|定序|定距|定比'),('相对指标和统计指数',r'相对指标|相对数|及格率|出勤率')]
    for topic,pattern in priorities:
        if re.search(pattern,stem):match=next(r for r in RULES if r[0]==topic);break
    # Stem gets priority: unrelated distractor text must not determine the explanation.
    for content in [stem,stem+' '+' '.join(opts)]:
        if match:break
        for r in RULES:
            if r[1].search(content):match=r;break
        if match:break
    if not match:return None
    topic,_,paras,tip,source=match
    out={'topic':topic,'paragraphs':list(paras),'tip':tip,'source':source}
    if q['type']!='判断题':
        neg=bool(re.search(r'不正确|说法错误|错误的是|错误的|不属于|不是|不包括|不适用|不能|不恰当|不宜',stem))
        selected='；'.join(label+'：'+text for label,text in chosen if text and '[配图' not in text)
        out['paragraphs'].append(('本题是反向选择题，要找出不符合上述条件或定义的选项。' if neg else '本题需按上述定义、适用条件和计算口径逐项判断。')+'原站答案为 '+ '、'.join(q['answer'])+'。'+('对应内容为“'+selected+'”。' if selected else '')+('多选题应检查所有选项，不能只选其中一项。' if q['type']=='多选题' else ''))
    else:
        out['paragraphs'].append('本题原站判断为“'+('正确' if q['answer']==['A'] else '错误')+'”。核对时注意题干中的否定、范围和适用条件，按上面的知识点理解，不只记字母。')
    return out
